// swiftlint:disable line_length
//
// Every line this rule flags in this file is one localized string — a generated
// symbol named after the English that is also the key in `Changelog.xcstrings`,
// which answers in eight languages. A name cannot be split across source lines,
// and the symbol is what the build checks the key by. The exemption is here so
// the 320-character warning can go on meaning what `.swiftlint.yml` says it
// means — a notice about runaway *code* — instead of firing on these lines.

import SwiftUI
import HelmRuntime
import HelmUI

/// The in-app changelog: structured, and localized from its own catalog
/// (`Changelog.xcstrings`, the English sentence is the key) so "What's New" reads
/// in the user's language. The repo's CHANGELOG.md stays the canonical English
/// record for GitHub.
///
/// **This list is written for the person using Helm, not for the person who
/// fixed it.** An entry says what is different for them and, where it helps,
/// one clause about what used to happen instead. What it never says is how the
/// defect worked: threads, logs, caches, memory and the names of internal
/// parts belong in CHANGELOG.md and in the commit, which is where somebody
/// looking for them will look. The rewrite that established this rule cut the
/// longest entries by roughly half, and deleted the ones that admitted in so
/// many words that they were not for the reader — an entry opening "a few
/// things you are unlikely to notice" is a note to the author.
public enum ChangeKind {
    case new, upd, fix

    /// NEW / UPD / FIX, the same three letters in every language.
    ///
    /// They were words — "Улучшено", "Correctif", "Melhoria" — and a word is a
    /// different length in each of eight languages and in each of three kinds.
    /// The badges sit in a column down the left of the list, so the widest one
    /// set the indent for every entry and the column came out ragged: Russian
    /// "Улучшено" ran half again as wide as "Испр." beside it. Three letters,
    /// uppercase, untranslated — the same convention as BETA and DEV, and the
    /// same width whatever the reader's language.
    public var label: String {
        switch self {
        case .new: return "NEW"
        case .upd: return "UPD"
        case .fix: return "FIX"
        }
    }

    public var color: Color {
        switch self {
        case .new: return .green
        case .upd: return .blue
        case .fix: return .orange
        }
    }
}

public struct ChangeItem: Identifiable {
    public let id = UUID()
    public let kind: ChangeKind
    public let text: String
}

public struct ChangelogEntry: Identifiable {
    public var id: String { version }
    public let version: String
    public let date: String
    public let items: [ChangeItem]
}

public enum Changelog {
    private static let bundles = LockedMemo<AppLanguage, Bundle>()

    /// One sentence in the app's language, read out of the language's own
    /// sub-bundle held for good.
    ///
    /// Not `L(_:)`: the first read of `entries` in each language would ask
    /// `String(localized:)`, dear on a large table, once per sentence. The
    /// symbol is still what makes a mistyped sentence a build error; a language the
    /// catalog lacks answers with the English that is the key.
    private static func line(_ sentence: LocalizedStringResource) -> String {
        let bundle = bundles.value(for: AppLanguage.current) {
            Bundle.module.url(forResource: AppLanguage.current.rawValue, withExtension: "lproj")
                .flatMap(Bundle.init(url:)) ?? Bundle.module
        }
        return bundle.localizedString(forKey: sentence.key, value: sentence.key, table: sentence.table)
    }

